import 'triiiceratops/element/register';
import type { TriiiceratopsViewerElement } from 'triiiceratops';

type ViewerState = NonNullable<TriiiceratopsViewerElement['viewerState']>;

const el = document.querySelector<TriiiceratopsViewerElement>(
    'triiiceratops-viewer',
)!;

function drive(state: ViewerState) {
    document
        .querySelector('button#next')!
        .addEventListener('click', () => state.nextCanvas());
}

// Listen first, then check: catches state published before or after this runs.
el.addEventListener('viewerstateavailable', (event) => {
    drive((event as CustomEvent<ViewerState>).detail);
});
if (el.viewerState) drive(el.viewerState);

import {
    TriiiceratopsViewer,
    useViewer,
    useViewerHandle,
} from 'triiiceratops/react';

export function Reader() {
    const handle = useViewerHandle();
    const state = useViewer(handle);

    return (
        <>
            <button type="button" onClick={() => state?.nextCanvas()}>
                Next canvas
            </button>
            <TriiiceratopsViewer
                handle={handle}
                manifestId="https://example.org/manifest.json"
                style={{ display: 'block', height: '600px' }}
            />
        </>
    );
}

import type { ViewerState } from 'triiiceratops';

declare const state: ViewerState;

// Step through the manifest, or jump to a canvas by id.
state.nextCanvas();
state.setCanvas('https://example.org/iiif/canvas/p3');

// Open the annotations panel if it is closed.
if (!state.showAnnotations) state.toggleAnnotations();

// Frame a detail of the current canvas, in canvas coordinates.
state.fitBounds({ x: 1200, y: 800, width: 600, height: 400 });

// Open a different manifest at a chosen canvas.
void state.setManifest('https://example.org/iiif/other/manifest.json', {
    canvasId: 'https://example.org/iiif/other/canvas/1',
});

import type { ViewerState } from 'triiiceratops';

declare const state: ViewerState;
declare const counter: HTMLElement;

const stop = state.subscribe(() => {
    counter.textContent = `${state.currentCanvasIndex + 1} / ${state.canvases.length}`;
});

// Later, when your control goes away:
stop();
